SELECT r.id, r.conversation_id, r.objective, r.status, r.status_reason, r.pause_reason, r.controller_spec, r.token_budget, r.tokens_used, r.time_used_seconds, r.autonomous_turns_used, r.consecutive_no_progress, r.last_continuation_fingerprint, r.created_at, r.updated_at FROM (SELECT data_rows.id, data_rows.should_delete, data_rows.conversation_id, data_rows.objective, data_rows.status, data_rows.status_reason, data_rows.pause_reason, data_rows.controller_spec, data_rows.token_budget, data_rows.tokens_used, data_rows.time_used_seconds, data_rows.autonomous_turns_used, data_rows.consecutive_no_progress, data_rows.last_continuation_fingerprint, data_rows.created_at, data_rows.updated_at FROM  (SELECT 0 AS should_delete, `id`, `conversation_id`, `objective`, `status`, `status_reason`, `pause_reason`, `controller_spec`, `token_budget`, `tokens_used`, `time_used_seconds`, `autonomous_turns_used`, `consecutive_no_progress`, `last_continuation_fingerprint`, `created_at`, `updated_at` FROM goal)  data_rows) r WHERE $criteria.CompositeIn("r", $WriterKeys)